sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var groupName;

    switch (current.current_priority.toString()) {
        case '1': // Critical
            groupName = 'Hostel Management Group';
            break;
        case '2': // High
            groupName = 'Hostel Admin Group';
            break;
        case '3': // Medium
        case '4': // Low
            groupName = 'Mess Staff Group';
            break;
        default:
            return;
    }

    var group = new GlideRecord('sys_user_group');
    group.addQuery('name', groupName);
    group.query();
    if (group.next()) {
        current.assignment_group = group.getUniqueValue();
        // No current.update() here either
    } else {
        gs.warn('Assignment group not found: ' + groupName);
    }

})(current, previous);
